    // descriptors, rather than scanning the whole ID space at each Finalize.
    os_unfair_lock_lock(&g_rmu);
    for (int n = (int)(uintptr_t)nvn_hm_get(&g_treg_serial, &ser); n; n = g_treg[n - 1].next) {
