    unsigned o = 0, nd = 0;
    pthread_mutex_lock(&g_smu);
    for (unsigned i = 0; i < g_vcg_n; i++) { uint64_t ser = g_vcg[i]; vc_set *s = nvn_hm_get(&g_vc, &ser);
        if (!s || !s->ghost) continue;
