static void treg_drop_pool_views(const void *pool) {
    os_unfair_lock_lock(&g_rmu);
    vc_drop_pool(pool);
    for (int i = 0; i < g_ntreg; i++) if (g_treg[i].ok && (const void *)g_treg[i].t.pool == pool) treg_gone(&g_treg[i]);
