        if (e) *e = [NSError errorWithDomain:@"nxnative.NVN.Pipeline" code:1
            userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"invalid depth/stencil pipeline formats %lu/%lu (compile=%d)",
