        for (uint64_t i = first; i < n; i++) if (g_gsr[i % GSR_N].fence >= fence) { rlo[nr] = g_gsr[i % GSR_N].lo; rhi[nr++] = g_gsr[i % GSR_N].hi; }
        pthread_mutex_unlock(&g_gsr_mu); }
    pthread_mutex_lock(&g_gml_mu);
    g_gml_logs++;
