        pthread_mutex_lock(&g_mu); int p = pool_peek(e[0]); double age = p >= 0 ? (double)(now - g_pools[p].born) / 1e6 : -1; pthread_mutex_unlock(&g_mu);
        if (age >= 0) { if (age < age_lo) age_lo = age; if (age > age_hi) age_hi = age; }
