}
// The texture slots (bit per slot 0-255) whose attachment this draw reads from the tile; 0 = none (then g_fb_tfn and the rest are not this draw's)
static int fb_tile_plan(NvProg *pr, uint32_t wm, uint64_t tile[4]) {
