    id<MTLBuffer> ab; size_t ao = arena_alloc((size_t)n * (32 + sizeof(ajob)), &ab); uint64_t ag = ab.gpuAddress + ao;   // n argument records (32 bytes apart), then the arrays jobs
    ajob *aj = (ajob *)((uint8_t *)ab.contents + ao + (size_t)n * 32);
